7	/// Utility for file operations: scanning dotfiles, copying files/directories, and resolving symlinks.
8	///
9	/// Note: Symlink creation/management is handled by `SymlinkManager`, not this module.
10	/// This module provides low-level file utilities only.
11	pub struct FileManager {
12	    home_dir: PathBuf,
13	}
14	
15	#[derive(Debug, Clone)]
16	pub struct Dotfile {
17	    /// Original path of the file
18	    pub original_path: PathBuf,
19	    /// Path relative to home directory
20	    pub relative_path: PathBuf,
21	    /// Whether this file is currently synced
22	    pub synced: bool,
23	    /// Description of the dotfile (if available from default list)
24	    pub description: Option<String>,
25	    /// Whether this file is a common file (shared across all profiles)
26	    pub is_common: bool,
27	    /// Whether this file was manually added via `config.custom_files` (not auto-detected)
28	    pub is_custom: bool,
29	}
