112	    /// Check if a path is a symlink
113	    #[must_use]
114	    pub fn is_symlink(&self, path: &Path) -> bool {
115	        if let Ok(metadata) = fs::symlink_metadata(path) {
116	            metadata.file_type().is_symlink()
117	        } else {
118	            false
119	        }
120	    }
