122	    /// Copy file or directory recursively
123	    pub fn copy_to_repo(&self, source: &Path, dest: &Path) -> Result<()> {
124	        info!("Starting copy operation: {:?} -> {:?}", source, dest);
125	
126	        // Remove destination if it exists (to avoid conflicts)
127	        if dest.exists() {
128	            if dest.is_dir() {
129	                info!("Removing existing directory at destination: {:?}", dest);
130	                fs::remove_dir_all(dest)
131	                    .with_context(|| format!("Failed to remove existing directory: {dest:?}"))?;
132	                debug!("Successfully removed existing directory: {:?}", dest);
133	            } else {
134	                info!("Removing existing file at destination: {:?}", dest);
135	                fs::remove_file(dest)
136	                    .with_context(|| format!("Failed to remove existing file: {dest:?}"))?;
137	                debug!("Successfully removed existing file: {:?}", dest);
138	            }
139	        }
140	
141	        // Create parent directory
142	        if let Some(parent) = dest.parent() {
143	            if !parent.exists() {
144	                debug!("Creating parent directory: {:?}", parent);
145	                fs::create_dir_all(parent)
146	                    .with_context(|| format!("Failed to create parent directory: {parent:?}"))?;
147	                info!("Created parent directory: {:?}", parent);
148	            }
149	        }
150	
151	        // Use metadata to check file type (follows symlinks)
152	        let source_metadata = fs::metadata(source)
153	            .with_context(|| format!("Failed to read metadata for source: {source:?}"))?;
154	
155	        if source_metadata.is_file() {
156	            let file_size = source_metadata.len();
157	            info!(
158	                "Copying file ({} bytes): {:?} -> {:?}",
159	                file_size, source, dest
160	            );
161	            let bytes_copied = fs::copy(source, dest)
162	                .with_context(|| format!("Failed to copy file from {source:?} to {dest:?}"))?;
163	            info!(
164	                "Successfully copied file ({} bytes): {:?}",
165	                bytes_copied, dest
166	            );
167	            debug!(
168	                "File copy complete: source={:?}, dest={:?}, size={}",
169	                source, dest, bytes_copied
170	            );
171	        } else if source_metadata.is_dir() {
172	            info!("Copying directory recursively: {:?} -> {:?}", source, dest);
173	            copy_dir_all(source, dest)
174	                .with_context(|| format!("Failed to copy directory from {source:?} to {dest:?}"))?;
175	            info!("Successfully copied directory: {:?} -> {:?}", source, dest);
176	        } else {
177	            warn!("Source path is neither file nor directory: {:?}", source);
178	            return Err(anyhow::anyhow!(
179	                "Source path is neither file nor directory: {source:?}"
180	            ));
181	        }
182	
183	        Ok(())
184	    }
