194	/// Recursively copy a directory, preserving symlinks.
195	///
196	/// NOTE: This function creates symlinks directly with `std::os::unix::fs::symlink()`
197	/// instead of using `SymlinkManager`. This is intentional because:
198	/// - These are **internal symlinks within dotfile content** (e.g., `~/.config/app/current -> versions/v1`)
199	/// - They are part of the user's configuration, not DotState-managed infrastructure
200	/// - `SymlinkManager` only tracks symlinks that link home files to the repo (e.g., `~/.zshrc -> repo/Profile/.zshrc`)
201	/// - Internal content symlinks should be preserved as-is without tracking
202	pub fn copy_dir_all(src: &Path, dst: &Path) -> Result<()> {
203	    debug!("Creating destination directory: {:?}", dst);
204	    fs::create_dir_all(dst)
205	        .with_context(|| format!("Failed to create destination directory: {dst:?}"))?;
206	
207	    let mut files_copied = 0;
208	    let mut dirs_copied = 0;
209	    let mut symlinks_copied = 0;
210	    let mut skipped = 0;
211	
212	    for entry in fs::read_dir(src).with_context(|| format!("Failed to read directory: {src:?}"))? {
213	        let entry = entry?;
214	        let path = entry.path();
215	        let file_name = entry.file_name();
216	        let dst_path = dst.join(&file_name);
217	
218	        // Check for symlinks first (before is_dir/is_file which follow symlinks)
219	        let file_type = entry.file_type()?;
220	        if file_type.is_symlink() {
221	            // Preserve symlinks as symlinks
222	            match fs::read_link(&path) {
223	                Ok(link_target) => {
224	                    debug!(
225	                        "Copying symlink: {:?} -> {:?} (target: {:?})",
226	                        path, dst_path, link_target
227	                    );
228	                    // Remove existing destination if it exists
229	                    if dst_path.symlink_metadata().is_ok() {
230	                        let _ = fs::remove_file(&dst_path);
231	                    }
232	                    #[cfg(unix)]
233	                    {
234	                        if let Err(e) = std::os::unix::fs::symlink(&link_target, &dst_path) {
235	                            warn!(
236	                                "Failed to create symlink {:?} -> {:?}: {}",
237	                                dst_path, link_target, e
238	                            );
239	                            skipped += 1;
240	                            continue;
241	                        }
242	                    }
243	                    #[cfg(windows)]
244	                    {
245	                        // On Windows, we need to know if target is file or directory
246	                        // For broken symlinks, default to file symlink
247	                        let target_is_dir = link_target.is_dir();
248	                        let result = if target_is_dir {
249	                            std::os::windows::fs::symlink_dir(&link_target, &dst_path)
250	                        } else {
251	                            std::os::windows::fs::symlink_file(&link_target, &dst_path)
252	                        };
253	                        if let Err(e) = result {
254	                            warn!(
255	                                "Failed to create symlink {:?} -> {:?}: {}",
256	                                dst_path, link_target, e
257	                            );
258	                            skipped += 1;
259	                            continue;
260	                        }
261	                    }
262	                    symlinks_copied += 1;
263	                }
264	                Err(e) => {
265	                    warn!("Failed to read symlink target for {:?}: {}", path, e);
266	                    skipped += 1;
267	                }
268	            }
269	        } else if file_type.is_dir() {
270	            debug!("Copying subdirectory: {:?} -> {:?}", path, dst_path);
271	            copy_dir_all(&path, &dst_path)?;
272	            dirs_copied += 1;
273	        } else {
274	            if let Ok(metadata) = path.metadata() {
275	                let file_size = metadata.len();
276	                debug!(
277	                    "Copying file ({} bytes): {:?} -> {:?}",
278	                    file_size, path, dst_path
279	                );
280	            } else {
281	                debug!("Copying file: {:?} -> {:?}", path, dst_path);
282	            }
283	            fs::copy(&path, &dst_path).with_context(|| format!("Failed to copy file: {path:?}"))?;
284	            files_copied += 1;
285	        }
286	    }
287	
288	    debug!(
289	        "Directory copy complete: {:?} -> {:?} ({} files, {} dirs, {} symlinks, {} skipped)",
290	        src, dst, files_copied, dirs_copied, symlinks_copied, skipped
291	    );
292	
293	    Ok(())
294	}
